                body = r' \\ '.join(' & '.join(row[:width]) for row in rows)
            layout = {'[': 'bmatrix', '(': 'pmatrix', '|': 'vmatrix'}[left[1]]
            text = text[:left.start()] + r'\begin{' + layout + '}' + body + r'\end{' + layout + '}' + text[closing.end() + right.end():]
